    { "id": "c12h4q12", "question": "The 'Basic Needs Approach' was initially proposed by:", "options": ["International Labour Organisation (ILO)", "World Health Organisation (WHO)", "UNESCO", "UNICEF"], "correctAnswer": 0, "explanation": "The ILO proposed the Basic Needs Approach, which identified six basic needs: health, education, food, water supply, sanitation, and housing." },
    { "id": "c12h4q13", "question": "Which of the following is an indicator of 'Access to Resources' in HDI?", "options": ["Purchasing Power Parity (PPP) in US$", "Total GDP of the country", "Number of banks per person", "Industrial output"], "correctAnswer": 0, "explanation": "Access to resources is measured by purchasing power in terms of US dollars." },
    { "id": "c12h4q14", "question": "Equity in human development refers to:", "options": ["Giving everyone the same amount of money", "Providing equal access to opportunities to everyone", "Equality in physical strength", "Equality in political parties"], "correctAnswer": 1, "explanation": "Equity means making equal access to opportunities available to everybody regardless of their gender, race, income, or caste." },
    { "id": "c12h4q15", "question": "Productivity in the context of human development means:", "options": ["Industrial productivity", "Human labor productivity or productivity in terms of human work", "Agricultural yield", "Machine efficiency"], "correctAnswer": 1, "explanation": "Productivity here refers to building capabilities in people to increase their work efficiency and contribution." },
    { "id": "c12h4q16", "question": "Which country ranks 131st (approx.) on the HDI 2020 list?", "options": ["India", "Pakistan", "Bangladesh", "Nepal"], "correctAnswer": 0, "explanation": "India's rank in the Human Development Index 2020 was 131." },
    { "id": "c12h4q17", "question": "The 'Income Approach' to human development assumes:", "options": ["Happiness is the only goal", "The level of income reflects the level of freedom a person enjoys", "Education is free", "Health is wealth"], "correctAnswer": 1, "explanation": "One of the oldest approaches, it links development to income, assuming higher income means higher development." },
    { "id": "c12h4q18", "question": "Human development is a process of ____________ people's choices.", "options": ["Enlarging", "Restricting", "Monitoring", "Ignoring"], "correctAnswer": 0, "explanation": "Enlarging choices and improving lives are the key goals of human development." },
    { "id": "c12h4q19", "question": "Which of the following is NOT a dimension of the Multidimensional Poverty Index (MPI)?", "options": ["Health", "Education", "Standard of Living", "Political Affiliation"], "correctAnswer": 3, "explanation": "MPI uses the same three dimensions as HDI: Health, Education, and Standard of Living." },
    { "id": "c12h4q20", "question": "Which South Asian country has significantly improved its HDI by focusing on health and education despite lower income?", "options": ["India", "Pakistan", "Sri Lanka", "Afghanistan"], "correctAnswer": 2, "explanation": "Sri Lanka has better human development indicators than many of its larger neighbors." },
    { "id": "c12h4q21", "question": "The 'Gross National Happiness' (GNH) index was pioneered by:", "options": ["India", "Bhutan", "Thailand", "Nepal"], "correctAnswer": 1, "explanation": "Bhutan is the only country in the world to officially measure Gross National Happiness." },
    { "id": "c12h4q22", "question": "A low HDI score (below 0.550) is typically associated with:", "options": ["High spending on health", "Political instability and social conflict", "Large oil reserves", "High literacy"], "correctAnswer": 1, "explanation": "Many countries with low HDI are characterized by civil war, famine, or high incidence of diseases." },
    { "id": "c12h4q23", "question": "Development means a 'qualitative change' which is always:", "options": ["Negative", "Value positive", "Neutral", "Constant"], "correctAnswer": 1, "explanation": "Development occurs when there is a positive change in quality." },
    { "id": "c12h4q24", "question": "Which of the following is a component of 'Sustainability'?", "options": ["Continuity of opportunities", "Environmental conservation", "Economic viability", "All of the above"], "correctAnswer": 3, "explanation": "Sustainability involves maintaining environmental, financial, and human resources for the future." },
    { "id": "c12h4q25", "question": "The 'Trickle Down Effect' is a part of which approach?", "options": ["Basic Needs Approach", "Growth Approach", "Capability Approach", "Welfare Approach"], "correctAnswer": 1, "explanation": "The Growth Approach assumes that benefits of GDP growth will trickle down to the poor." },
    { "id": "c12h4q26", "question": "Human Development is about:", "options": ["Building more factories", "Enlarging people's choices and improving their lives", "Winning more medals in Olympics", "Increasing the number of cars"], "correctAnswer": 1, "explanation": "The core of human development is the well-being and freedom of people." },
    { "id": "c12h4q27", "question": "Which of the following is a barrier to 'Equity'?", "options": ["Education", "Gender discrimination", "Universal healthcare", "Fair wages"], "correctAnswer": 1, "explanation": "Gender, race, or caste discrimination prevents people from having equal access to opportunities." },
    { "id": "c12h4q28", "question": "The 'Gender-Related Development Index' (GDI) measures:", "options": ["Total number of women in a country", "Disparities between men and women in HDI dimensions", "Number of women in parliament", "Female literacy alone"], "correctAnswer": 1, "explanation": "GDI measures achievements in the same dimensions as HDI but adjusted for gender inequality." },
    { "id": "c12h4q29", "question": "High Human Development is often found in small countries because:", "options": ["They have fewer people to manage", "They often have higher per capita resources and better governance", "They don't have military", "They have more land"], "correctAnswer": 1, "explanation": "Many small European nations and islands rank high due to targeted social spending and efficient governance." },
    { "id": "c12h4q30", "question": "What is the range of values for the HDI?", "options": ["-1 to +1", "0 to 1", "1 to 100", "0 to 100"], "correctAnswer": 1, "explanation": "The HDI score ranges from 0 (lowest) to 1 (highest)." },
    { "id": "c12h4q31", "question": "Which of the following countries has a very high level of human development (>0.800)?", "options": ["India", "Germany", "Bangladesh", "Nigeria"], "correctAnswer": 1, "explanation": "Germany is in the 'Very High' category of human development." },
    { "id": "c12h4q32", "question": "Education in HDI is measured by:", "options": ["Number of schools", "Mean years of schooling and expected years of schooling", "Literacy rate only", "Number of PhDs"], "correctAnswer": 1, "explanation": "Since 2010, the UNDP uses mean and expected years of schooling to calculate the education index." },
    { "id": "c12h4q33", "question": "'Human Rights' approach to development emphasizes:", "options": ["Economic growth", "Development as a right for all individuals", "Charity for the poor", "Technological advancement"], "correctAnswer": 1, "explanation": "This approach views development as a fundamental human right." },
    { "id": "c12h4q34", "question": "Which of the following is a challenge to human development in Africa?", "options": ["High life expectancy", "HIV/AIDS and other epidemics", "Over-industrialization", "Excessive urbanization"], "correctAnswer": 1, "explanation": "Epidemics like HIV/AIDS have significantly lowered life expectancy in several African nations, dragging down their HDI." },
    { "id": "c12h4q35", "question": "What is 'Growth without Development'?", "options": ["Increase in GDP but no improvement in standard of living", "Decrease in GDP and decrease in health", "Stable GDP with decreasing population", "Increase in literacy but no jobs"], "correctAnswer": 0, "explanation": "Growth is quantitative; development is qualitative. A country can grow economically without improving the lives of its citizens." },
    { "id": "c12h4q36", "question": "The 'Planetary Pressures-adjusted HDI' (PHDI) accounts for:", "options": ["Oil prices", "Carbon dioxide emissions and material footprint", "Space exploration", "Global warming only"], "correctAnswer": 1, "explanation": "PHDI adjusts the HDI for a country's environmental impact." },
    { "id": "c12h4q37", "question": "Which of the following is NOT a social indicator of development?", "options": ["Literacy rate", "Infant mortality rate", "GDP per capita", "Life expectancy"], "correctAnswer": 2, "explanation": "GDP per capita is an economic indicator, whereas others are social/demographic." },
    { "id": "c12h4q38", "question": "Equity promotes:", "options": ["Social justice", "Economic monopoly", "Political tyranny", "Environmental degradation"], "correctAnswer": 0, "explanation": "Equity ensures that benefits of development reach all sections of society, promoting social justice." },
    { "id": "c12h4q39", "question": "The 'Technological Development' leads to human development by:", "options": ["Replacing humans", "Providing tools to improve health, education, and connectivity", "Monitoring citizens", "Increasing pollution"], "correctAnswer": 1, "explanation": "Technology acts as an enabler to enlarge people's choices and capabilities." },
    { "id": "c12h4q40", "question": "Which of the following is the ultimate goal of human development?", "options": ["Wealth accumulation", "Creation of an environment where people can lead meaningful lives", "Industrial supremacy", "Space travel"], "correctAnswer": 1, "explanation": "The ultimate goal is to enable people to lead long, healthy, and creative lives." }
